"""Inspect the workspace: list files and, if a SQLite DB exists, show its schema."""

import os
import sqlite3

print("--- Files in workspace ---")
for entry in sorted(os.listdir(".")):
    print(entry)

print("\n--- SQLite databases found ---")
db_files = [f for f in os.listdir(".") if f.endswith((".db", ".sqlite", ".sqlite3"))]
if not db_files:
    print("(none)")

for db in db_files:
    print(f"\nDB: {db}")
    try:
        with sqlite3.connect(db) as conn:
            cur = conn.cursor()
            tables = cur.execute(
                "SELECT name FROM sqlite_master WHERE type='table' ORDER BY name"
            ).fetchall()
            for (table,) in tables:
                print(f"  table: {table}")
                for row in cur.execute(f'PRAGMA table_info("{table}")'):
                    print(f"    column: {row}")
                indexes = cur.execute(
                    f'PRAGMA index_list("{table}")'
                ).fetchall()
                for idx in indexes:
                    print(f"    index: {idx}")
    except sqlite3.Error as exc:
        print(f"  error reading DB: {exc}")

